const message = $('Telegram Trigger').first().json.message;
const query = String(message?.text || '').trim();
const chatId = message?.chat?.id;
if (!chatId) throw new Error('Telegram chat ID was not found');
if (!query) return [{json:{chatId,answer:'لطفاً سؤال خود را به‌صورت متن ارسال کنید'}}];
const html = String($json.data ?? $json.body ?? '');
const decode = s => s.replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'\"').replace(/&#39;|&apos;/gi,"'").replace(/&#8211;|&ndash;/gi,'–').replace(/&#8212;|&mdash;/gi,'—').replace(/&#(\d+);/g,(_,n)=>String.fromCharCode(Number(n)));
const strip = s => decode(s.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim());
const normalize = s => String(s).toLowerCase().replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/[ۀة]/g,'ه').replace(/\u200c/g,' ').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const stop = new Set(['از','به','در','با','برای','را','رو','که','این','اون','یک','چطور','چگونه','چی','چه','من','ما','و','یا','روی','میشه','شود','کنم','کردن','است','هست']);
const tokens = normalize(query).split(/\s+/).filter(x=>x.length>1 && !stop.has(x));
const results = [];
const re = /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
let match;
while ((match = re.exec(html))) {
  try {
    const url = new URL(match[1], 'https://sfiord.com/sup/');
    const title = strip(match[2]);
    if (url.hostname !== 'sfiord.com' || !title || title.length < 3) continue;
    const target = normalize(title);
    let score = 0;
    for (const token of tokens) {
      if (target.includes(token)) score += target === token ? 6 : 3;
      for (const word of target.split(' ')) if (word.startsWith(token) || token.startsWith(word)) score += 1;
    }
    if (score > 0) results.push({title,url:url.href.split('#')[0],score});
  } catch {}
}
const unique = [...new Map(results.sort((a,b)=>b.score-a.score).map(x=>[x.url,x])).values()].slice(0,5);
let answer;
if (unique.length) {
  answer = 'موارد مرتبط با سؤال شما در صفحه پشتیبانی اسفیورد:\n\n' + unique.map((x,i)=>`${i+1}  ${x.title}\n${x.url}`).join('\n\n');
} else {
  answer = 'مورد مرتبطی در صفحه پشتیبانی اسفیورد پیدا نشد\n\nمی‌توانید عبارت کوتاه‌تری مثل نصب دوربین  گارانتی  نرم افزار  مودم یا حافظه ابری ارسال کنید\n\nhttps://sfiord.com/sup/';
}
return [{json:{chatId,answer:answer.slice(0,4000)}}];
